bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true
test "$(docker exec deploy-gaybbs-1 sha256sum /app/gaybbs.mjs | cut -d' ' -f1)" = 22c930f364bcec223a0a3ddca9d04dbadf74d1bc4cffe4d08494ef8e1a4311b7
docker exec -i deploy-gaybbs-1 node --input-type=module <<'JS'
import fs from 'node:fs';
import https from 'node:https';
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE,'utf8').trim();
async function pending(){
 const a=await new Promise(resolve=>{
 const r=https.get('https://api.telegram.org/bot'+token+'/getWebhookInfo',{family:4,timeout:10000},res=>{
 let s='';res.on('data',c=>s+=c);res.on('end',()=>{try{const j=JSON.parse(s);resolve(j.ok&&!j.result.url?j.result.pending_update_count:null)}catch{resolve(null)}});
 });r.on('timeout',()=>r.destroy());r.on('error',()=>resolve(null));});
 if(!Number.isInteger(a))throw Error('QUEUE_READ_FAILED');
 return a;
}
const first=await pending();console.log('PENDING_FIRST='+first);
for(let i=0;i<6;i++){
 if(await pending()===0){console.log('QUEUE_DRAINED=PASS');process.exit(0);}
 await new Promise(r=>setTimeout(r,3000));
}
console.log('PENDING_LAST='+await pending());
JS
docker inspect -f 'RUNNING={{.State.Running}} RESTARTS={{.RestartCount}}' deploy-gaybbs-1
docker logs --since 5m --tail 1000 deploy-gaybbs-1 2>&1 | python3 -c 'import sys,re,collections
s=sys.stdin.read()
for k in ["GAYBBS_BOT_READY","GAYBBS_FATAL","GAYBBS_ERROR","409:","401:","429:","FetchError","AbortError","TimeoutError","ETELEGRAM","ETIMEDOUT","ECONNRESET","ECONNREFUSED","deleteWebhook","getUpdates"]: print("LOG_COUNT",k,s.count(k))
for k,v in sorted(collections.Counter(re.findall(r"\[GAYBBS_ERROR\]\s+(\w+)\s+(\w+)",s)).items()): print("BOT_ERROR",*k,v)'
